// ================== CẤU HÌNH ==================
const CONFIG = {
  WEBHOOK_SECRET: 'doi-chuoi-bi-mat-nay',
  JIRA_BASE_URL: 'https://your-company.atlassian.net',
  SUPABASE_URL: 'https://xxxxxxxx.supabase.co',
  TIMEZONE: 'Asia/Ho_Chi_Minh',
  POLL_LOOKBACK: '-30m',      // lượt quét định kỳ chỉ xét ticket có thay đổi trong khoảng này (rộng hơn chu kỳ quét để không sót)
  COMMENTS_PER_CHECK: 10,
  COMMENT_PREVIEW_CHARS: 700,
  CS_COMMENT_AUTHORS: [],     // tên hiển thị Jira của CS -> comment của họ được gắn nhãn (CS)
  IGNORE_COMMENT_AUTHORS: ['Automation for Jira'],
  STOP_WHEN_DONE: true,       // ticket sang Done -> báo lần cuối rồi ngừng theo dõi
  ATTACHMENT_PROXY_URL: 'https://YOUR-N8N-DOMAIN/webhook/jira-attachment', // Production URL của workflow Attachment Proxy
  ATTACHMENT_SECRET: 'doi-chuoi-bi-mat-anh',   // phải giống hệt trong workflow Attachment Proxy
  INCLUDE_NON_IMAGE_FILES: true, // cũng đưa link cho file log/pdf/video... không chỉ ảnh
  NOTE_IMAGE_MARKDOWN: false,    // true = chèn ![ảnh](link) để thử xem Crisp có hiện ảnh trong note không
};
// ==============================================
let keys = null, source = 'schedule';
if ($('Jira Webhook (optional)').isExecuted) {
  const w = $('Jira Webhook (optional)').first().json;
  if (CONFIG.WEBHOOK_SECRET && (w.query || {}).secret !== CONFIG.WEBHOOK_SECRET) return [];
  const b = w.body || {};
  const key = b.issue?.key || b.issue_key;
  if (!key) return [];
  keys = [String(key)];
  source = 'webhook';
}
return [{ json: { config: CONFIG, keys, source } }];

const st = $('Start').first().json;
const links = $input.all().map(x => x.json).filter(l => l && l.issue_key && l.session_id);
if (!links.length) return [];
const keys = [...new Set(links.map(l => l.issue_key))].slice(0, 200);
let jql = `key in (${keys.join(',')})`;
if (st.source === 'schedule') jql += ` AND updated >= ${st.config.POLL_LOOKBACK}`;
return [{ json: { jql, links } }];

const { links } = $('Build JQL').first().json;
const res = $input.first().json || {};
const issues = Array.isArray(res.issues) ? res.issues : [];
const out = [];
for (const iss of issues) {
  for (const l of links.filter(x => x.issue_key === iss.key)) {
    out.push({ json: {
      issue_key: iss.key,
      website_id: l.website_id,
      session_id: l.session_id,
      link: l,
      summary: iss.fields?.summary || '',
      status: iss.fields?.status?.name || '?',
      status_category: iss.fields?.status?.statusCategory?.key || '',
      updated: iss.fields?.updated || '',
      status_changed_at: iss.fields?.statuscategorychangedate || '',
      attachments: Array.isArray(iss.fields?.attachment) ? iss.fields.attachment : [],
    } });
  }
}
return out;   // rỗng = không ticket nào thay đổi -> dừng, không tạo note

function adfToText(n) {
  if (!n) return '';
  if (typeof n === 'string') return n;
  if (n.type === 'text') return n.text || '';
  if (n.type === 'hardBreak') return '\n';
  if (n.type === 'mention') return n.attrs?.text || '';
  if (n.type === 'media' || n.type === 'mediaInline') return `[Ảnh: ${n.attrs?.alt || 'không tên'}]`;
  if (n.type === 'inlineCard' || n.type === 'blockCard') return n.attrs?.url || '';
  const inner = (n.content || []).map(adfToText).join('');
  if (n.type === 'listItem') return '• ' + inner;
  return ['paragraph', 'heading', 'blockquote', 'codeBlock'].includes(n.type) ? inner + '\n' : inner;
}
function fmt(t, tz) {
  const d = typeof t === 'number' ? new Date(t) : new Date(t || Date.now());
  if (isNaN(d)) return '?';
  const p = Object.fromEntries(new Intl.DateTimeFormat('en-GB', { timeZone: tz, day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' })
    .formatToParts(d).map(x => [x.type, x.value]));
  return `${p.day}/${p.month}/${p.year} ${p.hour}:${p.minute}`;
}
const norm = v => String(v || '').toLowerCase();
const matchAny = (name, list) => (list || []).some(x => x && norm(name).includes(norm(x)));
const marker = (key, status, at) => `[jira-sync ${key} | status=${status} | at=${at}]`;
// ---- HMAC-SHA256 thuần JS (Code node của n8n mặc định không cho require('crypto')) ----
function sha256(bytes) {
  const frac = (x) => ((x - Math.floor(x)) * 4294967296) >>> 0;
  const primes = []; for (let n = 2; primes.length < 64; n++) if (primes.every(p => n % p)) primes.push(n);
  const K = primes.map(p => frac(Math.cbrt(p)));
  const H = primes.slice(0, 8).map(p => frac(Math.sqrt(p)));
  const len = bytes.length, total = ((len + 9 + 63) >> 6) << 6;
  const buf = new Uint8Array(total); buf.set(bytes); buf[len] = 0x80;
  const dv = new DataView(buf.buffer);
  dv.setUint32(total - 4, (len * 8) >>> 0); dv.setUint32(total - 8, Math.floor(len / 536870912));
  const W = new Uint32Array(64), r = (x, n) => (x >>> n) | (x << (32 - n));
  for (let o = 0; o < total; o += 64) {
    for (let i = 0; i < 16; i++) W[i] = dv.getUint32(o + i * 4);
    for (let i = 16; i < 64; i++) {
      const s0 = r(W[i - 15], 7) ^ r(W[i - 15], 18) ^ (W[i - 15] >>> 3);
      const s1 = r(W[i - 2], 17) ^ r(W[i - 2], 19) ^ (W[i - 2] >>> 10);
      W[i] = (W[i - 16] + s0 + W[i - 7] + s1) | 0;
    }
    let [a, b, c, d, e, f, g, h] = H;
    for (let i = 0; i < 64; i++) {
      const t1 = (h + (r(e, 6) ^ r(e, 11) ^ r(e, 25)) + ((e & f) ^ (~e & g)) + K[i] + W[i]) | 0;
      const t2 = ((r(a, 2) ^ r(a, 13) ^ r(a, 22)) + ((a & b) ^ (a & c) ^ (b & c))) | 0;
      h = g; g = f; f = e; e = (d + t1) | 0; d = c; c = b; b = a; a = (t1 + t2) | 0;
    }
    [a, b, c, d, e, f, g, h].forEach((v, i) => { H[i] = (H[i] + v) >>> 0; });
  }
  const out = new Uint8Array(32); H.forEach((v, i) => new DataView(out.buffer).setUint32(i * 4, v)); return out;
}
const utf8 = (s) => Uint8Array.from(unescape(encodeURIComponent(String(s))), ch => ch.charCodeAt(0));
function hmacHex(key, msg) {
  let k = utf8(key); if (k.length > 64) k = sha256(k);
  const kp = new Uint8Array(64); kp.set(k);
  const inner = new Uint8Array(64 + utf8(msg).length); inner.set(kp.map(x => x ^ 0x36)); inner.set(utf8(msg), 64);
  const ih = sha256(inner);
  const outer = new Uint8Array(96); outer.set(kp.map(x => x ^ 0x5c)); outer.set(ih, 64);
  return [...sha256(outer)].map(x => x.toString(16).padStart(2, '0')).join('');
}

// ---- Tìm file đính kèm thuộc về 1 comment ----
function mediaAlts(n, acc = []) {
  if (!n || typeof n !== 'object') return acc;
  if ((n.type === 'media' || n.type === 'mediaInline') && n.attrs) acc.push(n.attrs.alt || '');
  (n.content || []).forEach(c => mediaAlts(c, acc));
  return acc;
}
function commentAttachments(c, attachments) {
  const ids = new Set();
  const html = String(c.renderedBody || '');
  for (const m of html.matchAll(/\/attachment\/(?:content\/|thumbnail\/)?(\d+)/g)) ids.add(m[1]);      // 1. link ảnh trong HTML
  for (const m of html.matchAll(/\/secure\/(?:attachment|thumbnail)\/(\d+)\//g)) ids.add(m[1]);
  const cMs = Date.parse(c.created || '') || 0;
  const alts = mediaAlts(c.body);
  for (const alt of alts.filter(Boolean)) {                                                          // 2. khớp tên file
    const cands = attachments.filter(a => a.filename === alt)
      .sort((x, y) => Math.abs(Date.parse(x.created) - cMs) - Math.abs(Date.parse(y.created) - cMs));
    if (cands.length) ids.add(String(cands[0].id));
  }
  if (alts.length > ids.size) {                                                                      // 3. cùng người, ±3 phút
    attachments.filter(a => a.author?.accountId && a.author.accountId === c.author?.accountId
      && Math.abs((Date.parse(a.created) || 0) - cMs) <= 180000).forEach(a => ids.add(String(a.id)));
  }
  return attachments.filter(a => ids.has(String(a.id)));
}
const isImage = a => /^image\//.test(a?.mimeType || '');
const proxyUrl = (cfg, id, thumb) => `${cfg.ATTACHMENT_PROXY_URL}?id=${id}${thumb ? '&thumb=1' : ''}&sig=${hmacHex(cfg.ATTACHMENT_SECRET, String(id))}`;
const kb = n => (n >= 1048576 ? (n / 1048576).toFixed(1) + ' MB' : Math.max(1, Math.round((n || 0) / 1024)) + ' KB');

const cfg = $('Start').first().json.config;
const pairs = $('Pair Tickets with Chats').all().map(x => x.json);
const cmRes = $('Get Comments').all().map(x => x.json);
const msgRes = $input.all().map(x => x.json);
const nowMs = Date.now();
const out = [];

pairs.forEach((p, i) => {
  // 1. Mốc đã báo: ưu tiên dòng [jira-sync] mới nhất trong chatlog, không có thì lấy từ DB
  const msgs = Array.isArray(msgRes[i]?.data) ? msgRes[i].data : [];
  let mk = null;
  const re = /\[jira-sync ([A-Z][A-Z0-9_]+-\d+) \| status=([^|\]]*) \| at=([^\]]*)\]/g;
  for (const m of msgs) {
    if (m.type !== 'note' || typeof m.content !== 'string') continue;
    for (const g of m.content.matchAll(re)) {
      if (g[1] === p.issue_key && (!mk || m.timestamp > mk.ts)) mk = { status: g[2].trim(), at: g[3].trim(), ts: m.timestamp };
    }
  }
  const baseAtStr = mk?.at || p.link.last_seen_at || p.link.linked_at || null;
  const baseAt = Date.parse(baseAtStr || '') || 0;
  const baseStatus = mk?.status || p.link.last_status || null;

  // 2. Có gì mới hơn mốc?
  const comments = (Array.isArray(cmRes[i]?.comments) ? cmRes[i].comments : [])
    .filter(c => !matchAny(c.author?.displayName, cfg.IGNORE_COMMENT_AUTHORS))
    .filter(c => (Date.parse(c.created || '') || 0) > baseAt)
    .sort((a, b) => Date.parse(a.created) - Date.parse(b.created));
  const statusChanged = !!baseStatus && baseStatus !== p.status;
  const wanted = a => cfg.INCLUDE_NON_IMAGE_FILES || isImage(a);
  const used = new Set();
  const perComment = comments.map(c => {
    const files = commentAttachments(c, p.attachments).filter(wanted);
    files.forEach(a => used.add(String(a.id)));
    return files;
  });
  const looseFiles = p.attachments   // file đính kèm thẳng vào ticket, không nằm trong comment
    .filter(a => (Date.parse(a.created || '') || 0) > baseAt && !used.has(String(a.id)) && wanted(a))
    .sort((a, b) => Date.parse(a.created) - Date.parse(b.created));
  if (!comments.length && !statusChanged && !looseFiles.length) return;   // không có gì mới -> không tạo note
  const fileLines = (files, indent) => files.flatMap(a => {
    const icon = isImage(a) ? '🖼' : '📎';
    const lines = [`${indent}${icon} ${a.filename} (${kb(a.size)}): ${proxyUrl(cfg, a.id)}`];
    if (cfg.NOTE_IMAGE_MARKDOWN && isImage(a)) lines.push(`${indent}![${a.filename}](${proxyUrl(cfg, a.id, true)})`);
    return lines;
  });

  // 3. Soạn note
  const latestComment = comments[comments.length - 1];
  const latestLoose = looseFiles[looseFiles.length - 1];
  const latestChangeMs = Math.max(
    latestComment ? Date.parse(latestComment.created) : 0,
    latestLoose ? Date.parse(latestLoose.created) : 0,
    statusChanged ? (Date.parse(p.status_changed_at) > baseAt ? Date.parse(p.status_changed_at) : Date.parse(p.updated) || 0) : 0,
  );
  const isDone = p.status_category === 'done';
  const L = [
    `🔔 CẬP NHẬT JIRA · ${p.issue_key}`,
    p.summary,
    `${cfg.JIRA_BASE_URL}/browse/${p.issue_key}`,
    `🗓 Kiểm tra lúc ${fmt(nowMs, cfg.TIMEZONE)} · cập nhật mới nhất lúc ${fmt(latestChangeMs || nowMs, cfg.TIMEZONE)}` + (baseAt ? ` (lần báo trước: ${fmt(baseAt, cfg.TIMEZONE)})` : ''),
    '',
  ];
  if (statusChanged) L.push(`• Trạng thái: ${baseStatus} → ${p.status}`);
  else L.push(`• Trạng thái: ${p.status} (không đổi)`);
  if (comments.length) {
    L.push(`• ${comments.length} comment mới:`);
    for (const c of comments) {
      const who = c.author?.displayName || '?';
      const role = matchAny(who, cfg.CS_COMMENT_AUTHORS) ? 'CS' : 'tech';
      const text = adfToText(c.body).trim();
      const cut = text.length > cfg.COMMENT_PREVIEW_CHARS ? text.slice(0, cfg.COMMENT_PREVIEW_CHARS) + '… (xem tiếp trên Jira)' : text;
      L.push(`  – ${who} (${role}) · ${fmt(c.created, cfg.TIMEZONE)}`);
      L.push('    ' + cut.replace(/\n/g, '\n    '));
      L.push(...fileLines(perComment[comments.indexOf(c)], '    '));
    }
  }
  if (looseFiles.length) {
    L.push(`• ${looseFiles.length} file đính kèm mới trên ticket:`);
    L.push(...fileLines(looseFiles, '  '));
  }
  L.push('');
  if (isDone && cfg.STOP_WHEN_DONE) L.push('✅ Ticket đã hoàn tất. Hệ thống ngừng theo dõi tự động; dán lại link nếu cần theo dõi tiếp.');
  L.push('💡 Cần soạn tin báo khách? Mở Reply Assistant ở sidebar.');
  const cands = [latestComment?.created, latestLoose?.created].filter(Boolean)
    .sort((a, b) => Date.parse(b) - Date.parse(a));
  const newAt = cands[0] || baseAtStr || new Date(nowMs).toISOString();
  L.push(marker(p.issue_key, p.status, newAt));

  out.push({ json: {
    website_id: p.website_id,
    session_id: p.session_id,
    issue_key: p.issue_key,
    note: L.join('\n'),
    last_status: p.status,
    last_seen_at: newAt,
    active: !(isDone && cfg.STOP_WHEN_DONE),
  } });
});
return out;
